package io.github.turbopro.ism.bootstrap;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;
import org.springframework.http.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class PackageAuthoringIT extends SiteInitializationSupport {
    ResponseEntity<JsonNode> call(String token,HttpMethod method,String path,String key,Object body){var h=new HttpHeaders();h.setBearerAuth(token);if(key!=null)h.set("Idempotency-Key",key);return http.exchange("/api/console/"+path,method,new HttpEntity<>(body,h),JsonNode.class);}
    JsonNode ok(String token,HttpMethod method,String path,String key,Object body){var r=call(token,method,path,key,body);assertThat(r.getStatusCode()).as(path+" "+r.getBody()).isEqualTo(HttpStatus.OK);return r.getBody().path("data");}
    String key(){return UUID.randomUUID().toString();}
    JsonNode plan(String token){return ok(token,HttpMethod.POST,"packages",key(),Map.of("code","PA_"+IDS.incrementAndGet(),"name","配置验收套餐"));}
    Map<String,Object> version(int no,boolean enabled){return Map.of("versionNo",no,"name","配置版"+no,"modules",List.of(Map.of("moduleCode","SUPPLIER","enabled",enabled,"quotas",Map.of("SUPPLIER_COUNT",100))));}
    JsonNode draft(String t,String p){return ok(t,HttpMethod.POST,"packages/"+p+"/versions",key(),version(1,true));}
    @Test void createsEditsValidatesPublishesAndIsAvailableForTenantCreation(){var t=login(true);var p=plan(t);String id=p.path("id").asText();var v=draft(t,id);String vid=v.path("id").asText();var edit=Map.of("name","修正版","version",0,"modules",List.of(Map.of("moduleCode","SUPPLIER","enabled",true,"quotas",Map.of("SUPPLIER_COUNT",120))));
        var saved=ok(t,HttpMethod.PUT,"package-versions/"+vid,key(),edit);assertThat(saved.path("version").asInt()).isOne();assertThat(ok(t,HttpMethod.POST,"package-versions/"+vid+"/validate",null,null).path("valid").asBoolean()).isTrue();
        var pub=ok(t,HttpMethod.POST,"package-versions/"+vid+"/publish",key(),Map.of("version",1));assertThat(pub.path("status").asText()).isEqualTo("PUBLISHED");assertThat(jdbc.queryForObject("SELECT status FROM plt_package WHERE id=?",String.class,Long.parseLong(id))).isEqualTo("ACTIVE");
        var opts=ok(t,HttpMethod.GET,"tenants/package-options?q="+p.path("code").asText(),null,null);assertThat(opts.path("total").asInt()).isOne();assertThat(opts.path("items").get(0).path("id").asText()).isEqualTo(vid);
        var tenant=ok(t,HttpMethod.POST,"tenants",key(),Map.of("code","PA-TENANT-"+IDS.incrementAndGet(),"name","发布套餐租户","timezone","Asia/Shanghai","locale","zh-CN","packageVersionId",vid));assertThat(tenant.path("packageVersionId").asText()).isEqualTo(vid);
        assertThat(call(t,HttpMethod.PUT,"package-versions/"+vid,key(),Map.of("name","覆盖发布版","version",2,"modules",version(2,true).get("modules"))).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);
        for(String action:List.of("PACKAGE_CREATE","PACKAGE_VERSION_CREATE","PACKAGE_VERSION_UPDATE","PACKAGE_VERSION_PUBLISH"))assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sys_audit_event WHERE object_id=? AND action=?",Integer.class,action.equals("PACKAGE_CREATE")?id:vid,action)).isOne();
    }
    @Test void idempotencyReplaysAndRejectsChangedRequestAndDuplicateCodes(){var t=login(true);String k=key(),code="PA_"+IDS.incrementAndGet();var body=Map.of("code",code,"name","幂等套餐");var p=ok(t,HttpMethod.POST,"packages",k,body);assertThat(ok(t,HttpMethod.POST,"packages",k,body)).isEqualTo(p);assertThat(call(t,HttpMethod.POST,"packages",k,Map.of("code",code,"name","不同名称")).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);assertThat(call(t,HttpMethod.POST,"packages",key(),body).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);
        String id=p.path("id").asText(),vk=key();var v=ok(t,HttpMethod.POST,"packages/"+id+"/versions",vk,version(1,true));assertThat(ok(t,HttpMethod.POST,"packages/"+id+"/versions",vk,version(1,true))).isEqualTo(v);assertThat(call(t,HttpMethod.POST,"packages/"+id+"/versions",key(),version(1,true)).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);
        String pk=key(),vid=v.path("id").asText();var published=ok(t,HttpMethod.POST,"package-versions/"+vid+"/publish",pk,Map.of("version",0));assertThat(ok(t,HttpMethod.POST,"package-versions/"+vid+"/publish",pk,Map.of("version",0))).isEqualTo(published);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sys_audit_event WHERE object_id=? AND action='PACKAGE_VERSION_PUBLISH'",Integer.class,vid)).isOne();
    }
    @Test void rejectsInvalidModulesQuotasAndStaleEditsWithoutPartialReplacement(){var t=login(true);var p=plan(t);String id=p.path("id").asText();var v=draft(t,id);String vid=v.path("id").asText();for(Object mods:List.of(List.of(Map.of("moduleCode","MISSING","enabled",true,"quotas",Map.of())),List.of(Map.of("moduleCode","SUPPLIER","enabled",true,"quotas",Map.of("BAD",-1))),Arrays.asList((Object)null),List.of(Map.of("moduleCode","SUPPLIER","enabled",true,"quotas",Map.of("bad code",1))))){var r=call(t,HttpMethod.PUT,"package-versions/"+vid,key(),Map.of("name","非法变更","version",0,"modules",mods));assertThat(r.getStatusCode().value()).isIn(400,422);}
        assertThat(call(t,HttpMethod.PUT,"package-versions/"+vid,key(),Map.of("name","旧版本","version",99,"modules",version(1,true).get("modules"))).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);assertThat(jdbc.queryForObject("SELECT version FROM plt_package_version WHERE id=?",Integer.class,vid)).isZero();assertThat(jdbc.queryForObject("SELECT JSON_EXTRACT(quota_json,'$.SUPPLIER_COUNT') FROM plt_package_module WHERE package_version_id=?",String.class,vid)).isEqualTo("100");
        var disabled=ok(t,HttpMethod.POST,"packages/"+id+"/versions",key(),version(2,false));assertThat(ok(t,HttpMethod.POST,"package-versions/"+disabled.path("id").asText()+"/validate",null,null).path("valid").asBoolean()).isFalse();assertThat(call(t,HttpMethod.POST,"package-versions/"+disabled.path("id").asText()+"/publish",key(),Map.of("version",0)).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
    }
    @Test void rechecksModuleAndParentAvailabilityAtPublish(){var t=login(true);var p=plan(t);String id=p.path("id").asText(),vid=draft(t,id).path("id").asText();assertThat(ok(t,HttpMethod.POST,"package-versions/"+vid+"/validate",null,null).path("valid").asBoolean()).isTrue();
        jdbc.update("UPDATE plt_module SET status='DISABLED' WHERE module_code='SUPPLIER'");try{assertThat(call(t,HttpMethod.POST,"package-versions/"+vid+"/publish",key(),Map.of("version",0)).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);}finally{jdbc.update("UPDATE plt_module SET status='ACTIVE' WHERE module_code='SUPPLIER'");}
        jdbc.update("UPDATE plt_package SET status='OFFLINE' WHERE id=?",id);assertThat(call(t,HttpMethod.POST,"package-versions/"+vid+"/publish",key(),Map.of("version",0)).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);assertThat(call(t,HttpMethod.POST,"packages/"+id+"/versions",key(),version(2,true)).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);assertThat(jdbc.queryForObject("SELECT status FROM plt_package_version WHERE id=?",String.class,vid)).isEqualTo("DRAFT");
    }
    @Test void auditFailureRollsBackPublicationAndParentActivationThenRetriesOriginalKey()throws Exception{var t=login(true);var p=plan(t);String id=p.path("id").asText(),vid=draft(t,id).path("id").asText(),pk=key();trigger("CREATE TRIGGER pa_audit_fail BEFORE INSERT ON sys_audit_event FOR EACH ROW BEGIN IF NEW.action='PACKAGE_VERSION_PUBLISH' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test audit failure'; END IF; END");try{assertThat(call(t,HttpMethod.POST,"package-versions/"+vid+"/publish",pk,Map.of("version",0)).getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);}finally{trigger("DROP TRIGGER pa_audit_fail");}assertThat(jdbc.queryForObject("SELECT status FROM plt_package WHERE id=?",String.class,id)).isEqualTo("DRAFT");assertThat(jdbc.queryForObject("SELECT version FROM plt_package_version WHERE id=?",Integer.class,vid)).isZero();ok(t,HttpMethod.POST,"package-versions/"+vid+"/publish",pk,Map.of("version",0));}
    @Test void concurrentEditsAndPublishCannotOverwritePublishedGrants()throws Exception{var t=login(true);String id=plan(t).path("id").asText(),vid=draft(t,id).path("id").asText();var pool=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);var edit=pool.submit(()->{start.await();return call(t,HttpMethod.PUT,"package-versions/"+vid,key(),Map.of("name","竞争编辑","version",0,"modules",version(1,true).get("modules"))).getStatusCode().value();});var pub=pool.submit(()->{start.await();return call(t,HttpMethod.POST,"package-versions/"+vid+"/publish",key(),Map.of("version",0)).getStatusCode().value();});start.countDown();assertThat(List.of(edit.get(20,TimeUnit.SECONDS),pub.get(20,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);}finally{pool.shutdownNow();}}
    void trigger(String sql)throws Exception{try(var c=java.sql.DriverManager.getConnection(MYSQL.getJdbcUrl(),"root",MYSQL.getPassword());var stmt=c.createStatement()){stmt.execute(sql);}}
    @Test void missingOptimisticVersionsAreRejectedBeforeWriting(){var t=login(true);String id=plan(t).path("id").asText(),vid=draft(t,id).path("id").asText();
        assertThat(call(t,HttpMethod.PUT,"package-versions/"+vid,key(),Map.of("name","无版本","modules",version(1,true).get("modules"))).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
        assertThat(call(t,HttpMethod.POST,"package-versions/"+vid+"/publish",key(),Map.of()).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
        assertThat(jdbc.queryForObject("SELECT version FROM plt_package_version WHERE id=?",Integer.class,vid)).isZero();
        assertThat(jdbc.queryForObject("SELECT status FROM plt_package WHERE id=?",String.class,id)).isEqualTo("DRAFT");
    }
    @Test void supportHasNoWriteOrModuleDirectoryAccess(){var admin=login(true);var support=login(false);String p=plan(admin).path("id").asText(),vid=draft(admin,p).path("id").asText();assertThat(call(support,HttpMethod.GET,"package-modules",null,null).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(call(support,HttpMethod.POST,"packages",key(),Map.of("code","FORBIDDEN","name","越权")).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(call(support,HttpMethod.PUT,"package-versions/"+vid,key(),Map.of("name","越权","version",0,"modules",version(1,true).get("modules"))).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(call(support,HttpMethod.POST,"package-versions/"+vid+"/publish",key(),Map.of("version",0)).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);}
}
